const items = $input.all();
const week = new Date().toISOString().substring(0,7);
const cutoff = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
const thisWeek = items.filter(i => i.json.created_at >= cutoff && i.json.status !== 'archived');
return [{ json: { findings: thisWeek.map(i=>i.json), count: thisWeek.length, week } }];

const items = $input.all();
const cutoff = new Date(Date.now() - 7*24*60*60*1000).toISOString();
const recent = items.filter(i => i.json.timestamp >= cutoff);
return [{ json: { errors: recent.map(i=>i.json), error_count: recent.length } }];

const all = $input.all();
const findingsItem = all.find(i => i.json.findings !== undefined) || { json: { findings: [], count: 0, week: new Date().toISOString().substring(0,7) } };
const errorsItem = all.find(i => i.json.errors !== undefined) || { json: { errors: [], error_count: 0 } };
return [{ json: { findings: findingsItem.json.findings, findings_count: findingsItem.json.count, week: findingsItem.json.week, errors: errorsItem.json.errors, error_count: errorsItem.json.error_count } }];

const apiResp = $input.first().json;
const data = $('Prepare Newsletter Prompt').first().json;
const newsletter = apiResp.content?.[0]?.text || 'Error: no content in API response';
const { prompt, ...rest } = data;
return [{ json: { ...rest, newsletter_content: newsletter, generated_at: new Date().toISOString() } }];

const data = $input.first().json;
const content = data.newsletter_content || '';

function parseMarkdown(text) {
  const lines = text.split('\n');
  let html = '';
  let inList = false;

  for (const line of lines) {
    if (inList && !line.startsWith('- ') && !line.match(/^\s+Sources:/)) {
      html += '</ul>';
      inList = false;
    }

    if (line.startsWith('## ')) {
      const title = line.substring(3).trim();
      html += `<h2 style="color:#1a2744;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;border-left:4px solid #e85d04;padding-left:12px;margin:28px 0 10px 0;">${title}</h2>`;
    } else if (line.trim() === '---') {
      html += '<hr style="border:none;border-top:1px solid #e5e7eb;margin:24px 0;">';
    } else if (line.match(/^\s*Sources:/)) {
      const sourcesContent = line.replace(/^\s*Sources:\s*/, '');
      const withLinks = sourcesContent.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" style="color:#e85d04;text-decoration:none;">$1</a>');
      html += `<p style="color:#9ca3af;font-size:12px;margin:2px 0 10px 18px;">Sources: ${withLinks}</p>`;
    } else if (line.startsWith('- ')) {
      if (!inList) {
        html += '<ul style="margin:8px 0 8px 0;padding-left:18px;">';
        inList = true;
      }
      const itemText = line.substring(2)
        .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
        .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" style="color:#e85d04;text-decoration:none;">$1</a>');
      html += `<li style="margin:6px 0;color:#374151;font-size:14px;line-height:1.65;">${itemText}</li>`;
    } else if (line.trim() === '') {
      if (inList) { html += '</ul>'; inList = false; }
    } else {
      const paraText = line
        .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
        .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" style="color:#e85d04;text-decoration:none;">$1</a>');
      html += `<p style="color:#374151;font-size:14px;line-height:1.7;margin:8px 0;">${paraText}</p>`;
    }
  }

  if (inList) html += '</ul>';
  return html;
}

const bodyHtml = parseMarkdown(content);

const formattedDate = new Date(data.generated_at).toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

const now = new Date();
const dayOfWeek = now.getDay();
const monday = new Date(now);
monday.setDate(now.getDate() - (dayOfWeek === 0 ? 6 : dayOfWeek - 1));
const friday = new Date(monday);
friday.setDate(monday.getDate() + 4);
const monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const startMonth = monthNames[monday.getMonth()];
const endMonth = monthNames[friday.getMonth()];
const formattedWeek = monday.getMonth() === friday.getMonth()
  ? `${startMonth} ${monday.getDate()}\u2013${friday.getDate()}, ${friday.getFullYear()}`
  : `${startMonth} ${monday.getDate()} \u2013 ${endMonth} ${friday.getDate()}, ${friday.getFullYear()}`;

const newsletter_html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width,initial-scale=1.0">
</head>
<body style="margin:0;padding:0;background-color:#f0f2f5;font-family:Arial,Helvetica,sans-serif;">
  <div style="max-width:600px;margin:32px auto;background:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.10);">

    <div style="background:#1a2744;padding:28px 32px;">
      <div style="color:#e85d04;font-size:10px;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;margin-bottom:6px;">PING IDENTITY</div>
      <div style="color:#ffffff;font-size:20px;font-weight:700;margin:0;">Product Intelligence</div>
      <div style="color:#94a3b8;font-size:13px;margin-top:4px;">Weekly Intel &mdash; ${formattedWeek}</div>
    </div>

    <div style="padding:28px 32px 20px 32px;">
      ${bodyHtml}
    </div>

    <div style="background:#f8fafc;padding:16px 32px;border-top:1px solid #e5e7eb;">
      <p style="color:#9ca3af;font-size:11px;margin:0;text-align:center;">
        Generated by Product Intelligence OS &middot; ${formattedDate}
      </p>
    </div>

  </div>
</body>
</html>`;

return [{ json: { ...data, newsletter_html, week_label: formattedWeek } }];
